import React from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import { ToastContainer } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';
import { AuthProvider, useAuth } from './context/AuthContext';
import { DashboardLayout } from './components/layout/DashboardLayout';
import { LoadingSpinner } from './components/common';

import LandingPage from './pages/public/LandingPage';
import { LoginPage, RegisterPage } from './pages/public/AuthPages';
import { AdminDashboard, AdminBanks, AdminCompanies, AdminConnectors } from './pages/admin/AdminPages';
import { AdminApplications, AdminUsers, AdminReports, AdminAuditLogs, AdminMessages, AdminSettings } from './pages/admin/AdminExtra';
import { AdminBankPolicy } from './pages/admin/BankPolicyPage';
import { CompanyCategoryPage } from './pages/admin/CompanyCategoryPage';
import { CompanyDashboard, CompanyJoinRequests, CompanyConnectors, CompanyBanks, CompanyApplications, CompanyEarnings, CompanyMessages, CompanyReports, CompanySettings } from './pages/company/CompanyPages';
import { ConnectorDashboard, ConnectorCompanies, ConnectorApplicationsList, ConnectorApplicationDetail, ConnectorNewApplication, ConnectorCommissions, ConnectorNotifications, ConnectorProfile } from './pages/connector/ConnectorPages';
import { BankDashboard, BankCompanies, BankSalesManagers, BankApplications, BankSanctions, BankQueries, BankSettings } from './pages/bank/BankPages';

const ProtectedRoute: React.FC<{ children: React.ReactNode; roles?: string[] }> = ({ children, roles }) => {
  const { user, loading } = useAuth();
  if (loading) return <LoadingSpinner fullPage />;
  if (!user) return <Navigate to="/login" replace />;
  if (roles && !roles.includes(user.role)) return <Navigate to="/" replace />;
  return <>{children}</>;
};

const HomeRedirect: React.FC = () => {
  const { user, loading } = useAuth();
  if (loading) return <LoadingSpinner fullPage />;
  if (!user) return <LandingPage />;
  const routes: Record<string, string> = { admin: '/admin/dashboard', company: '/company/dashboard', connector: '/connector/dashboard', bank: '/bank/dashboard', sm: '/bank/dashboard' };
  return <Navigate to={routes[user.role] || '/login'} replace />;
};

const AL: React.FC<{ c: React.ReactNode }> = ({ c }) => <ProtectedRoute roles={['admin']}><DashboardLayout>{c}</DashboardLayout></ProtectedRoute>;
const CL: React.FC<{ c: React.ReactNode }> = ({ c }) => <ProtectedRoute roles={['company']}><DashboardLayout>{c}</DashboardLayout></ProtectedRoute>;
const NL: React.FC<{ c: React.ReactNode }> = ({ c }) => <ProtectedRoute roles={['connector']}><DashboardLayout>{c}</DashboardLayout></ProtectedRoute>;
const BL: React.FC<{ c: React.ReactNode }> = ({ c }) => <ProtectedRoute roles={['bank','sm']}><DashboardLayout>{c}</DashboardLayout></ProtectedRoute>;
const BOL: React.FC<{ c: React.ReactNode }> = ({ c }) => <ProtectedRoute roles={['bank']}><DashboardLayout>{c}</DashboardLayout></ProtectedRoute>; // bank only, not sm — Bank Policy is bank-owner functionality

export default function App() {
  return (
    <Router>
      <AuthProvider>
        <ToastContainer position="top-right" autoClose={3000} theme="light" />
        <Routes>
          <Route path="/" element={<HomeRedirect />} />
          <Route path="/login" element={<LoginPage />} />
          <Route path="/register" element={<RegisterPage />} />

          <Route path="/admin/dashboard" element={<AL c={<AdminDashboard />} />} />
          <Route path="/admin/banks" element={<AL c={<AdminBanks />} />} />
          <Route path="/admin/companies" element={<AL c={<AdminCompanies />} />} />
          <Route path="/admin/connectors" element={<AL c={<AdminConnectors />} />} />
          <Route path="/admin/applications" element={<AL c={<AdminApplications />} />} />
          <Route path="/admin/users" element={<AL c={<AdminUsers />} />} />
          <Route path="/admin/bank-policy" element={<AL c={<AdminBankPolicy />} />} />
          <Route path="/admin/company-category" element={<AL c={<CompanyCategoryPage />} />} />
          <Route path="/admin/messages" element={<AL c={<AdminMessages />} />} />
          <Route path="/admin/reports" element={<AL c={<AdminReports />} />} />
          <Route path="/admin/audit-logs" element={<AL c={<AdminAuditLogs />} />} />
          <Route path="/admin/settings" element={<AL c={<AdminSettings />} />} />

          <Route path="/company/dashboard" element={<CL c={<CompanyDashboard />} />} />
          <Route path="/company/join-requests" element={<CL c={<CompanyJoinRequests />} />} />
          <Route path="/company/connectors" element={<CL c={<CompanyConnectors />} />} />
          <Route path="/company/banks" element={<CL c={<CompanyBanks />} />} />
          <Route path="/company/applications" element={<CL c={<CompanyApplications />} />} />
          <Route path="/company/earnings" element={<CL c={<CompanyEarnings />} />} />
          <Route path="/company/messages" element={<CL c={<CompanyMessages />} />} />
          <Route path="/company/reports" element={<CL c={<CompanyReports />} />} />
          <Route path="/company/settings" element={<CL c={<CompanySettings />} />} />

          <Route path="/connector/dashboard" element={<NL c={<ConnectorDashboard />} />} />
          <Route path="/connector/companies" element={<NL c={<ConnectorCompanies />} />} />
          <Route path="/connector/applications" element={<NL c={<ConnectorApplicationsList />} />} />
          <Route path="/connector/applications/new" element={<NL c={<ConnectorNewApplication />} />} />
          <Route path="/connector/applications/:id" element={<NL c={<ConnectorApplicationDetail />} />} />
          <Route path="/connector/commissions" element={<NL c={<ConnectorCommissions />} />} />
          <Route path="/connector/notifications" element={<NL c={<ConnectorNotifications />} />} />
          <Route path="/connector/profile" element={<NL c={<ConnectorProfile />} />} />

          <Route path="/bank/dashboard" element={<BL c={<BankDashboard />} />} />
          <Route path="/bank/companies" element={<BL c={<BankCompanies />} />} />
          <Route path="/bank/sales-managers" element={<BL c={<BankSalesManagers />} />} />
          <Route path="/bank/applications" element={<BL c={<BankApplications />} />} />
          <Route path="/bank/bank-policy" element={<BOL c={<AdminBankPolicy />} />} />
          <Route path="/bank/company-category" element={<BOL c={<CompanyCategoryPage />} />} />
          <Route path="/bank/sanctions" element={<BL c={<BankSanctions />} />} />
          <Route path="/bank/queries" element={<BL c={<BankQueries />} />} />
          <Route path="/bank/settings" element={<BL c={<BankSettings />} />} />

          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </AuthProvider>
    </Router>
  );
}
