export function BankSanctions() {
  const [apps, setApps] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    appAPI.getAll({}).then(r => {
      const sanctioned = r.data.applications.filter((a: any) =>
        a.bankAssignments?.some((ba: any) => ['sanctioned','agreement','disbursement','closed'].includes(ba.status))
      );
      setApps(sanctioned);
    }).finally(() => setLoading(false));
  }, []);

  return (
    <div>
      <PageHeader title="Sanction Tracker" subtitle="Sanctioned and disbursed loans" breadcrumbs={['Bank', 'Sanctions']} />
      <div className="card">
        {loading ? <LoadingSpinner /> : apps.length === 0 ? <EmptyState title="No sanctioned loans yet" /> : (
          <table className="w-full">
            <thead className="bg-slate-50">
              <tr><th className="table-th">App ID</th><th className="table-th">Applicant</th><th className="table-th">Loan Type</th><th className="table-th">Sanction Amount</th><th className="table-th">Sanction Date</th><th className="table-th">Status</th><th className="table-th">Letter</th></tr>
            </thead>
            <tbody>
              {apps.map((a: any) => {
                const ba = a.bankAssignments?.find((b: any) => ['sanctioned','agreement','disbursement','closed'].includes(b.status));
                return ba ? (
                  <tr key={a._id} className="table-row">
                    <td className="table-td font-mono text-xs text-primary">{a.applicationId}</td>
                    <td className="table-td font-medium">{a.applicantDetails?.name}</td>
                    <td className="table-td text-sm">{a.loanType}</td>
                    <td className="table-td font-semibold text-emerald-600">₹{(ba.sanctionAmount || 0).toLocaleString('en-IN')}</td>
                    <td className="table-td text-sm">{ba.sanctionDate ? new Date(ba.sanctionDate).toLocaleDateString('en-IN') : '—'}</td>
                    <td className="table-td"><StatusBadge status={ba.status} /></td>
                    <td className="table-td">
                      {ba.sanctionLetterUrl ? (
                        <a href={ba.sanctionLetterUrl} target="_blank" rel="noreferrer" className="btn-secondary text-xs px-2 py-1 flex items-center gap-1 w-fit"><FiDownload /> Download</a>
                      ) : <span className="text-slate-400 text-xs">—</span>}
                    </td>
                  </tr>
                ) : null;
              })}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

export function BankQueries() {
  const [apps, setApps] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    appAPI.getAll({}).then(r => {
      const withQueries = r.data.applications.filter((a: any) =>
        a.bankAssignments?.some((ba: any) => ba.queries?.some((q: any) => q.status === 'pending'))
      );
      setApps(withQueries);
    }).finally(() => setLoading(false));
  }, []);

  return (
    <div>
      <PageHeader title="Pending Queries" subtitle="Queries awaiting connector response" breadcrumbs={['Bank', 'Queries']} />
      {loading ? <LoadingSpinner /> : apps.length === 0 ? <EmptyState title="No pending queries" description="All queries have been resolved." /> : (
        <div className="space-y-4">
          {apps.map((a: any) => (
            <div key={a._id} className="card">
              <div className="flex items-center gap-2 mb-3">
                <span className="font-mono text-xs font-bold text-primary">{a.applicationId}</span>
                <span className="text-sm text-slate-600">{a.applicantDetails?.name}</span>
                <span className="text-xs text-slate-400">·</span>
                <span className="text-sm text-slate-500">{a.loanType}</span>
              </div>
              {a.bankAssignments?.map((ba: any) => ba.queries?.filter((q: any) => q.status === 'pending').map((q: any) => (
                <div key={q._id} className="bg-amber-50 border border-amber-200 rounded-lg p-3 mb-2">
                  <p className="text-sm font-medium text-amber-800 mb-1">{ba.bankName}</p>
                  <p className="text-sm text-slate-700">❓ {q.question}</p>
                  <p className="text-xs text-slate-400 mt-1">{new Date(q.raisedAt).toLocaleString('en-IN')}</p>
                </div>
              )))}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

