  const [pwForm, setPwForm] = useState({ currentPassword: '', newPassword: '' });
  return (
    <div>
      <PageHeader title="Settings" breadcrumbs={['Bank', 'Settings']} />
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className="card">
          <h3 className="font-semibold text-slate-800 mb-4">Account Info</h3>
          <div className="space-y-3 text-sm">
            <div className="flex justify-between py-2 border-b"><span className="text-slate-500">Name</span><span>{user?.name}</span></div>
            <div className="flex justify-between py-2 border-b"><span className="text-slate-500">Email</span><span>{user?.email}</span></div>
            <div className="flex justify-between py-2"><span className="text-slate-500">Role</span><span className="capitalize">{user?.role}</span></div>
          </div>
        </div>
        <div className="card">
          <h3 className="font-semibold text-slate-800 mb-4">Change Password</h3>
          <div className="space-y-4">
            <div><label className="label">Current Password</label><input className="input" type="password" value={pwForm.currentPassword} onChange={e => setPwForm(p => ({ ...p, currentPassword: e.target.value }))} /></div>
            <div><label className="label">New Password</label><input className="input" type="password" value={pwForm.newPassword} onChange={e => setPwForm(p => ({ ...p, newPassword: e.target.value }))} /></div>
            <button className="btn-primary" onClick={async () => {
              try { await authAPI.changePassword(pwForm); toast.success('Password changed'); }
              catch { toast.error('Failed'); }
            }}>Update</button>
          </div>
        </div>
      </div>
    </div>
  );
