function MonthYearPicker({ value, onChange, placeholder = '----------, ----' }: { value: string; onChange: (v: string) => void; placeholder?: string }) {
  const [open, setOpen] = useState(false);
  const [viewYear, setViewYear] = useState(() => (value ? Number(value.split('-')[0]) : new Date().getFullYear()));
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handler = (e: MouseEvent) => {
      if (ref.current && !ref.current.contains(e.target as Node)) setOpen(false);
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, []);

  const selectedMonthIdx = value ? Number(value.split('-')[1]) - 1 : -1;
  const selectedYear = value ? Number(value.split('-')[0]) : null;
  const display = value ? `${MONTHS[selectedMonthIdx]}, ${selectedYear}` : placeholder;

  const pick = (monthIdx: number) => {
    const mm = String(monthIdx + 1).padStart(2, '0');
    onChange(`${viewYear}-${mm}`);
    setOpen(false);
  };

  const thisMonth = () => {
    const now = new Date();
    setViewYear(now.getFullYear());
    onChange(`${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`);
    setOpen(false);
  };

  return (
    <div className="relative" ref={ref}>
      <button type="button" className="input text-left w-full" onClick={() => setOpen(o => !o)}>
        <span className={value ? '' : 'text-slate-400'}>{display}</span>
      </button>

      {open && (
        <div className="absolute z-20 mt-1 w-64 bg-white border border-slate-200 rounded-lg shadow-lg p-3">
          <div className="flex items-center justify-between bg-slate-100 rounded px-2 py-1.5 mb-3">
            <button type="button" className="px-2 text-slate-500 hover:text-slate-800" onClick={() => setViewYear(y => y - 1)}>‹</button>
            <span className="font-medium text-slate-700">{viewYear}</span>
            <button type="button" className="px-2 text-slate-500 hover:text-slate-800" onClick={() => setViewYear(y => y + 1)}>›</button>
          </div>

          <div className="grid grid-cols-4 gap-2 mb-3">
            {MONTHS.map((m, idx) => {
              const isSelected = selectedYear === viewYear && selectedMonthIdx === idx;
              return (
                <button
                  key={m}
                  type="button"
                  onClick={() => pick(idx)}
                  className={`text-sm py-1.5 rounded-md ${
                    isSelected ? 'bg-blue-600 text-white font-semibold' : 'text-slate-700 hover:bg-slate-100'
                  }`}
                >
                  {m}
                </button>
              );
            })}
          </div>

          <div className="flex items-center justify-between text-xs">
            <button type="button" className="text-blue-600 hover:underline" onClick={() => onChange('')}>Clear</button>
            <button type="button" className="text-blue-600 hover:underline" onClick={thisMonth}>This month</button>
          </div>
        </div>
      )}
    </div>
  );
}


