export function ConnectorCompanies() {
  const [companies, setCompanies] = useState<any[]>([]);
  const [sentRequests, setSentRequests] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  const load = async () => {
    setLoading(true);
    try {
      const [compRes, reqRes] = await Promise.all([listAPI.getCompanies(), joinAPI.getSent()]);
      setCompanies(compRes.data);
      setSentRequests(reqRes.data);
    } finally { setLoading(false); }
  };
  useEffect(() => { load(); }, []);

  const getRequestStatus = (companyId: string) => sentRequests.find(r => r.toCompanyId?._id === companyId || r.toCompanyId === companyId)?.status;

  const sendRequest = async (companyId: string) => {
    try { await joinAPI.send(companyId); toast.success('Join request sent!'); load(); }
    catch (err: any) { toast.error(err?.response?.data?.message || 'Failed'); }
  };

  return (
    <div>
      <PageHeader title="DSA Companies" subtitle="Send join requests to start submitting applications" breadcrumbs={['Connector', 'Companies']} />
      {loading ? <LoadingSpinner /> : companies.length === 0 ? <EmptyState title="No companies found" /> : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {companies.map((c: any) => {
            const status = getRequestStatus(c._id);
            return (
              <div key={c._id} className="card">
                <div className="flex items-start justify-between mb-3">
                  <div className="w-10 h-10 rounded-lg bg-primary-50 flex items-center justify-center text-primary font-bold">{c.companyName?.charAt(0)}</div>
                  {status && <StatusBadge status={status} />}
                </div>
                <h3 className="font-bold text-slate-800">{c.companyName}</h3>
                <p className="text-sm text-slate-500 mt-0.5">{c.city || 'India'} · {c.email}</p>
                <div className="flex gap-4 text-sm text-slate-500 mt-3">
                  <span>{c.bankingRelations?.filter((r: any) => r.status === 'approved').length || 0} Banks</span>
                  <span>{c.connectorRelations?.filter((r: any) => r.status === 'approved').length || 0} Connectors</span>
                </div>
                <div className="mt-4">
                  {status === 'approved' ? (
                    <div className="text-emerald-600 text-sm font-medium flex items-center gap-1"><FiCheckCircle /> Connected</div>
                  ) : status === 'pending' ? (
                    <div className="text-amber-600 text-sm font-medium">Request Pending...</div>
                  ) : (
                    <button onClick={() => sendRequest(c._id)} className="btn-primary text-sm w-full flex items-center justify-center gap-2"><FiSend /> Send Join Request</button>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}


export function ConnectorApplicationsList() {
  const [apps, setApps] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [filterType, setFilterType] = useState('');
  const [dropdownOpen, setDropdownOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);
  const navigate = useNavigate();

  const load = () => { setLoading(true); appAPI.getAll({ loanType: filterType }).then(r => setApps(r.data.applications)).finally(() => setLoading(false)); };
  useEffect(() => { load(); }, [filterType]);

  // Close dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(e.target as Node)) {
        setDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const selectedLabel = filterType || 'All Loan Types';

  return (
    <div>
      <PageHeader title="My Applications" subtitle={`${apps.length} applications`} breadcrumbs={['Connector', 'Applications']}
        actions={<button className="btn-primary flex items-center gap-2 text-sm" onClick={() => navigate('/connector/applications/new')}><FiPlus /> New Application</button>} />

      <div className="card mb-4">
        <div className="relative w-full sm:w-72" ref={dropdownRef}>
          <button
            type="button"
            onClick={() => setDropdownOpen(o => !o)}
            className="input w-full flex items-center justify-between text-left"
          >
            <span className="truncate">{selectedLabel}</span>
            <span className={`ml-2 text-slate-400 transition-transform ${dropdownOpen ? 'rotate-180' : ''}`}>▾</span>
          </button>

          {dropdownOpen && (
            <div className="absolute left-0 right-0 mt-1 bg-white border border-slate-200 rounded-lg shadow-lg z-50 max-h-72 overflow-y-auto">
              <div
                className={`px-4 py-2.5 text-sm cursor-pointer hover:bg-primary-50 ${filterType === '' ? 'bg-primary-50 text-primary font-semibold' : 'text-slate-700'}`}
                onClick={() => { setFilterType(''); setDropdownOpen(false); }}
              >
                All Loan Types
              </div>
              {LOAN_TYPES.map(lt => (
                <div
                  key={lt}
                  className={`px-4 py-2.5 text-sm cursor-pointer hover:bg-primary-50 ${filterType === lt ? 'bg-primary-50 text-primary font-semibold' : 'text-slate-700'}`}
                  onClick={() => { setFilterType(lt); setDropdownOpen(false); }}
                >
                  {lt}
                </div>
              ))}
            </div>
          )}
        </div>
      </div>

      {loading ? <LoadingSpinner /> : apps.length === 0 ? (
        <EmptyState title="No applications yet" description="Start by submitting a loan application." action={<button className="btn-primary text-sm" onClick={() => navigate('/connector/applications/new')}>New Application</button>} />
      ) : (
        <div className="space-y-4">
          {apps.map((a: any) => (
            <div key={a._id} className="card hover:shadow-md transition-shadow cursor-pointer" onClick={() => navigate(`/connector/applications/${a._id}`)}>
              <div className="flex items-start justify-between flex-wrap gap-3">
                <div>
                  <div className="flex items-center gap-2 mb-1">
                    <span className="font-mono text-xs font-bold text-primary">{a.applicationId}</span>
                    <StatusBadge status={a.overallStatus} />
                  </div>
                  <h3 className="font-semibold text-slate-800">{a.applicantDetails?.name}</h3>
                  <p className="text-sm text-slate-500">{a.loanType} · ₹{(a.loanAmount || 0).toLocaleString('en-IN')}</p>
                </div>
                <div className="text-right">
                  <p className="text-sm text-slate-500">{new Date(a.createdAt).toLocaleDateString('en-IN')}</p>
                  <p className="text-xs text-slate-400">{a.bankAssignments?.length || 0} bank(s)</p>
                </div>
              </div>
              <div className="flex flex-wrap gap-2 mt-3">
                {a.bankAssignments?.map((ba: any) => (
                  <div key={ba._id} className="flex items-center gap-1.5 bg-slate-50 rounded-lg px-2 py-1 text-xs">
                    <span className="font-medium text-slate-700">{ba.bankName}</span>
                    <StatusBadge status={ba.status} />
                    {ba.unmaskRequested && !ba.unmaskApproved && <span className="text-amber-600 font-medium">⚠ Unmask Req</span>}
                  </div>
                ))}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

