import React, { useEffect, useState } from 'react';
import { bankPolicyAPI, adminAPI } from '../../services/api';
import { PageHeader, LoadingSpinner, EmptyState, Modal, ConfirmModal } from '../../components/common';
import { FiPlus, FiEdit, FiEye, FiToggleLeft, FiToggleRight, FiDownload, FiUpload } from 'react-icons/fi';
import { toast } from 'react-toastify';
import { LOAN_TYPES } from '../../types';
import { useAuth } from '../../context/AuthContext';

// ── Defaults for a brand-new policy ──────────────────────────────────────────
const emptyPolicy = () => ({
  bankId: '',
  loanType: LOAN_TYPES[0],
  policyVersion: 'v1',
  effectiveDate: new Date().toISOString().slice(0, 10),
  status: 'active',
  eligibility: {
    minAge: 21, maxAge: 60, minSalary: 0, minCibil: 700, maxFOIR: 50,
    maxMultiplier: 0, maxLoanAmount: 0, minLoanAmount: 0, maxTenure: 0,
  },
  enquiryPolicy: { windowDays: 30, maxEnquiries: 3 },
  bouncePolicy: { windowMonths: 3, maxBounces: 0 },
  employmentPolicy: { allowedProfiles: [], restrictedProfiles: [], allowedCompanies: [], restrictedCompanies: [] },
  dpdPolicy: { maxDPD: 0, allow90PlusDPD: false },
  loanRules: { maxActiveLoans: 0, maxSTPL: 0, btAllowed: false, topUpAllowed: false, maxBT: 0, odBT: false, nocRequired: false },
  roi: { categoryA: 0, categoryB: 0, categoryC: 0, categoryD: 0, loanAmountWiseROI: [], openMarketDoable: true },
  specialNotes: '',
  customRules: [],
});

// Small helper: comma-separated text field <-> string[]
const CsvField: React.FC<{ label: string; value: string[]; onChange: (v: string[]) => void; placeholder?: string }> = ({ label, value, onChange, placeholder }) => (
  <div>
    <label className="label">{label}</label>
    <input
      className="input"
      placeholder={placeholder || 'Comma separated (e.g. Salaried, Self-Employed)'}
      value={(value || []).join(', ')}
      onChange={e => onChange(e.target.value.split(',').map(s => s.trim()).filter(Boolean))}
    />
  </div>
);

const SectionTitle: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <h4 className="font-semibold text-slate-700 text-sm border-b pb-2 mb-3 mt-6 first:mt-0">{children}</h4>
);

export function AdminBankPolicy() {
  const { user } = useAuth();
  const isBankUser = user?.role === 'bank'; // when opened from /bank/bank-policy
  const [policies, setPolicies] = useState<any[]>([]);
  const [banks, setBanks] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [viewing, setViewing] = useState<any>(null);
  const [editing, setEditing] = useState<any>(null);
  const [toggleId, setToggleId] = useState<string | null>(null);
  const [search, setSearch] = useState('');
  const [total, setTotal] = useState(0);
  const [form, setForm] = useState<any>(emptyPolicy());
  const [saving, setSaving] = useState(false);

  // ── Excel import/template (Bank Policy module) ──
  const [showImportModal, setShowImportModal] = useState(false);
  const [importBankId, setImportBankId] = useState('');
  const [importFile, setImportFile] = useState<File | null>(null);
  const [importing, setImporting] = useState(false);

  const load = () => {
    setLoading(true);
    bankPolicyAPI.getAll({ search, limit: 50 })
      .then(r => { setPolicies(r.data.policies); setTotal(r.data.total); })
      .finally(() => setLoading(false));
  };

  useEffect(() => { load(); }, [search]);

  // Admin sees every bank in the dropdown. A bank user only ever sees (and
  // can only ever save to) their own bank — fetched from /bank-policy/my-bank.
  useEffect(() => {
    if (isBankUser) {
      bankPolicyAPI.getMyBank().then(r => {
        setBanks([r.data]);
        setImportBankId(r.data._id);
      }).catch(() => toast.error('No bank profile linked to this account — contact Admin'));
    } else {
      adminAPI.getBanks({ limit: 200 }).then(r => setBanks(r.data.banks || []));
    }
  }, [isBankUser]);

  const openAdd = () => {
    setEditing(null);
    setForm({ ...emptyPolicy(), bankId: isBankUser && banks[0] ? banks[0]._id : '' });
    setShowModal(true);
  };
  const openEdit = (p: any) => {
    setEditing(p);
    setForm({ ...emptyPolicy(), ...p, bankId: p.bankId?._id || p.bankId, effectiveDate: p.effectiveDate ? p.effectiveDate.slice(0, 10) : '' });
    setShowModal(true);
  };

  const handleSave = async () => {
    if (!form.bankId) { toast.error('Please select a bank'); return; }
    setSaving(true);
    try {
      if (editing) { await bankPolicyAPI.update(editing._id, form); toast.success('Bank Policy updated'); }
      else { await bankPolicyAPI.create(form); toast.success('Bank Policy created'); }
      setShowModal(false); setEditing(null); load();
    } catch (err: any) { toast.error(err?.response?.data?.message || 'Save failed'); }
    finally { setSaving(false); }
  };

  const handleToggle = async () => {
    if (!toggleId) return;
    try { await bankPolicyAPI.toggleStatus(toggleId); toast.success('Status updated'); setToggleId(null); load(); }
    catch { toast.error('Failed to update status'); }
  };

  // ── Excel template + import handlers ──
  const handleDownloadTemplate = async () => {
    try {
      const res = await bankPolicyAPI.downloadTemplate();
      const url = window.URL.createObjectURL(new Blob([res.data]));
      const a = document.createElement('a');
      a.href = url; a.download = 'bank-policy-template.xlsx';
      document.body.appendChild(a); a.click(); a.remove();
      window.URL.revokeObjectURL(url);
    } catch { toast.error('Failed to download template'); }
  };

  const openImport = () => {
    setImportFile(null);
    setImportBankId(isBankUser && banks[0] ? banks[0]._id : '');
    setShowImportModal(true);
  };

  const handleImport = async () => {
    if (!importFile) { toast.error('Please choose an Excel file'); return; }
    if (!isBankUser && !importBankId) { toast.error('Please select a bank'); return; }
    setImporting(true);
    try {
      await bankPolicyAPI.importExcel(importFile, importBankId);
      toast.success('Bank Policy imported from Excel');
      setShowImportModal(false); load();
    } catch (err: any) { toast.error(err?.response?.data?.message || 'Import failed'); }
    finally { setImporting(false); }
  };

  // ── Custom rule builder helpers ──
  const addCustomRule = () => setForm((p: any) => ({
    ...p,
    customRules: [...(p.customRules || []), { ruleName: '', field: '', operator: '>=', value: '', failMessage: '' }],
  }));
  const updateCustomRule = (i: number, key: string, val: any) => setForm((p: any) => {
    const rules = [...(p.customRules || [])];
    rules[i] = { ...rules[i], [key]: val };
    return { ...p, customRules: rules };
  });
  const removeCustomRule = (i: number) => setForm((p: any) => ({
    ...p, customRules: (p.customRules || []).filter((_: any, idx: number) => idx !== i),
  }));

  // ── ROI slab builder helpers ──
  const addRoiSlab = () => setForm((p: any) => ({
    ...p, roi: { ...p.roi, loanAmountWiseROI: [...(p.roi.loanAmountWiseROI || []), { minAmount: 0, maxAmount: 0, roi: 0 }] },
  }));
  const updateRoiSlab = (i: number, key: string, val: number) => setForm((p: any) => {
    const slabs = [...(p.roi.loanAmountWiseROI || [])];
    slabs[i] = { ...slabs[i], [key]: val };
    return { ...p, roi: { ...p.roi, loanAmountWiseROI: slabs } };
  });
  const removeRoiSlab = (i: number) => setForm((p: any) => ({
    ...p, roi: { ...p.roi, loanAmountWiseROI: (p.roi.loanAmountWiseROI || []).filter((_: any, idx: number) => idx !== i) },
  }));

  return (
    <div>
      <PageHeader
        title="Bank Policy"
        subtitle={`${total} policies configured`}
        breadcrumbs={[isBankUser ? 'Bank' : 'Admin', 'Bank Policy']}
        actions={
          <div className="flex items-center gap-2">
            <button className="btn-secondary flex items-center gap-2 text-sm" onClick={handleDownloadTemplate}><FiDownload /> Template</button>
            <button className="btn-secondary flex items-center gap-2 text-sm" onClick={openImport}><FiUpload /> Import Excel</button>
            <button className="btn-primary flex items-center gap-2 text-sm" onClick={openAdd}><FiPlus /> Add Policy</button>
          </div>
        }
      />

      <div className="card">
        <div className="flex items-center justify-between gap-3 mb-4 flex-wrap">
          <input className="input max-w-xs" placeholder="Search by bank or version..." value={search} onChange={e => setSearch(e.target.value)} />
        </div>

        {loading ? <LoadingSpinner /> : policies.length === 0 ? (
          <EmptyState title="No bank policies yet" description="Add a policy so eligibility can be auto-checked when connectors submit leads." action={<button className="btn-primary" onClick={openAdd}>Add Policy</button>} />
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full">
              <thead className="bg-slate-50">
                <tr>
                  <th className="table-th">Bank</th>
                  <th className="table-th">Loan Type</th>
                  <th className="table-th">Version</th>
                  <th className="table-th">Effective Date</th>
                  <th className="table-th">Status</th>
                  <th className="table-th">Actions</th>
                </tr>
              </thead>
              <tbody>
                {policies.map((p: any) => (
                  <tr key={p._id} className="table-row">
                    <td className="table-td font-medium">
                      {p.bankName || p.bankId?.bankName}
                      <span className="text-slate-400 font-normal text-xs ml-1">
                        (...{(p.bankId?._id || p.bankId || '').toString().slice(-6)})
                      </span>
                    </td>
                    <td className="table-td">{p.loanType}</td>
                    <td className="table-td font-mono text-xs">{p.policyVersion}</td>
                    <td className="table-td">{p.effectiveDate ? new Date(p.effectiveDate).toLocaleDateString('en-IN') : '—'}</td>
                    <td className="table-td"><span className={p.status === 'active' ? 'badge-green' : 'badge-gray'}>{p.status}</span></td>
                    <td className="table-td">
                      <div className="flex items-center gap-2">
                        <button onClick={() => setViewing(p)} className="text-slate-500 hover:text-slate-700 p-1" title="View"><FiEye /></button>
                        <button onClick={() => openEdit(p)} className="text-primary hover:text-primary-700 p-1" title="Edit"><FiEdit /></button>
                        <button onClick={() => setToggleId(p._id)} className="text-slate-500 hover:text-slate-700 p-1" title={p.status === 'active' ? 'Deactivate' : 'Activate'}>
                          {p.status === 'active' ? <FiToggleRight className="text-emerald-500 text-lg" /> : <FiToggleLeft className="text-slate-400 text-lg" />}
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* ── Add / Edit Modal ── */}
      <Modal open={showModal} onClose={() => setShowModal(false)} title={editing ? 'Edit Bank Policy' : 'Add Bank Policy'} size="max-w-4xl">
        <div className="space-y-1 max-h-[70vh] overflow-y-auto pr-1">

          <SectionTitle>General Information</SectionTitle>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="label">Bank *</label>
              {isBankUser ? (
                <input className="input bg-slate-50" value={banks[0]?.bankName || 'Loading...'} disabled />
              ) : (
                <select className="input" value={form.bankId} onChange={e => setForm((p: any) => ({ ...p, bankId: e.target.value }))}>
                  <option value="">Select bank...</option>
                  {banks.map(b => <option key={b._id} value={b._id}>{b.bankName} (...{b._id.slice(-6)})</option>)}
                </select>
              )}
            </div>
            <div>
              <label className="label">Loan Type *</label>
              <select className="input" value={form.loanType} onChange={e => setForm((p: any) => ({ ...p, loanType: e.target.value }))}>
                {LOAN_TYPES.map(lt => <option key={lt} value={lt}>{lt}</option>)}
              </select>
            </div>
          </div>
          <div className="grid grid-cols-3 gap-4 mt-3">
            <div><label className="label">Policy Version</label><input className="input" value={form.policyVersion} onChange={e => setForm((p: any) => ({ ...p, policyVersion: e.target.value }))} /></div>
            <div><label className="label">Effective Date</label><input type="date" className="input" value={form.effectiveDate} onChange={e => setForm((p: any) => ({ ...p, effectiveDate: e.target.value }))} /></div>
            <div>
              <label className="label">Status</label>
              <select className="input" value={form.status} onChange={e => setForm((p: any) => ({ ...p, status: e.target.value }))}>
                <option value="active">Active</option>
                <option value="inactive">Inactive</option>
              </select>
            </div>
          </div>

          <SectionTitle>Eligibility</SectionTitle>
          <div className="grid grid-cols-3 gap-4">
            {[
              ['minAge', 'Minimum Age'], ['maxAge', 'Maximum Age'], ['minSalary', 'Minimum Salary'],
              ['minCibil', 'Minimum CIBIL'], ['maxFOIR', 'Maximum FOIR (%)'], ['maxMultiplier', 'Maximum Multiplier'],
              ['maxLoanAmount', 'Maximum Loan Amount'], ['minLoanAmount', 'Minimum Loan Amount'], ['maxTenure', 'Maximum Tenure (months)'],
            ].map(([key, label]) => (
              <div key={key}>
                <label className="label">{label}</label>
                <input type="number" className="input" value={form.eligibility[key]} onChange={e => setForm((p: any) => ({ ...p, eligibility: { ...p.eligibility, [key]: Number(e.target.value) } }))} />
              </div>
            ))}
          </div>

          <SectionTitle>Enquiry Policy</SectionTitle>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="label">Window</label>
              <select className="input" value={form.enquiryPolicy.windowDays} onChange={e => setForm((p: any) => ({ ...p, enquiryPolicy: { ...p.enquiryPolicy, windowDays: Number(e.target.value) } }))}>
                <option value={30}>30 Days</option><option value={60}>60 Days</option><option value={90}>90 Days</option>
              </select>
            </div>
            <div><label className="label">Max Enquiries Allowed</label><input type="number" className="input" value={form.enquiryPolicy.maxEnquiries} onChange={e => setForm((p: any) => ({ ...p, enquiryPolicy: { ...p.enquiryPolicy, maxEnquiries: Number(e.target.value) } }))} /></div>
          </div>

          <SectionTitle>Bounce Policy</SectionTitle>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="label">Window</label>
              <select className="input" value={form.bouncePolicy.windowMonths} onChange={e => setForm((p: any) => ({ ...p, bouncePolicy: { ...p.bouncePolicy, windowMonths: Number(e.target.value) } }))}>
                <option value={3}>3 Months</option><option value={6}>6 Months</option><option value={12}>12 Months</option>
              </select>
            </div>
            <div><label className="label">Max Bounces Allowed</label><input type="number" className="input" value={form.bouncePolicy.maxBounces} onChange={e => setForm((p: any) => ({ ...p, bouncePolicy: { ...p.bouncePolicy, maxBounces: Number(e.target.value) } }))} /></div>
          </div>

          <SectionTitle>Employment Policy</SectionTitle>
          <div className="grid grid-cols-2 gap-4">
            <CsvField label="Allowed Profiles" value={form.employmentPolicy.allowedProfiles} onChange={v => setForm((p: any) => ({ ...p, employmentPolicy: { ...p.employmentPolicy, allowedProfiles: v } }))} />
            <CsvField label="Restricted Profiles" value={form.employmentPolicy.restrictedProfiles} onChange={v => setForm((p: any) => ({ ...p, employmentPolicy: { ...p.employmentPolicy, restrictedProfiles: v } }))} />
            <CsvField label="Allowed Companies" value={form.employmentPolicy.allowedCompanies} onChange={v => setForm((p: any) => ({ ...p, employmentPolicy: { ...p.employmentPolicy, allowedCompanies: v } }))} />
            <CsvField label="Restricted Companies" value={form.employmentPolicy.restrictedCompanies} onChange={v => setForm((p: any) => ({ ...p, employmentPolicy: { ...p.employmentPolicy, restrictedCompanies: v } }))} />
          </div>

          <SectionTitle>DPD Policy</SectionTitle>
          <div className="grid grid-cols-2 gap-4 items-end">
            <div><label className="label">Maximum DPD</label><input type="number" className="input" value={form.dpdPolicy.maxDPD} onChange={e => setForm((p: any) => ({ ...p, dpdPolicy: { ...p.dpdPolicy, maxDPD: Number(e.target.value) } }))} /></div>
            <label className="flex items-center gap-2 text-sm cursor-pointer pb-2">
              <input type="checkbox" className="rounded" checked={form.dpdPolicy.allow90PlusDPD} onChange={e => setForm((p: any) => ({ ...p, dpdPolicy: { ...p.dpdPolicy, allow90PlusDPD: e.target.checked } }))} />
              90+ DPD Allowed
            </label>
          </div>

          <SectionTitle>Loan Rules</SectionTitle>
          <div className="grid grid-cols-3 gap-4">
            <div><label className="label">Maximum Active Loans</label><input type="number" className="input" value={form.loanRules.maxActiveLoans} onChange={e => setForm((p: any) => ({ ...p, loanRules: { ...p.loanRules, maxActiveLoans: Number(e.target.value) } }))} /></div>
            <div><label className="label">Maximum STPL</label><input type="number" className="input" value={form.loanRules.maxSTPL} onChange={e => setForm((p: any) => ({ ...p, loanRules: { ...p.loanRules, maxSTPL: Number(e.target.value) } }))} /></div>
            <div><label className="label">Maximum BT</label><input type="number" className="input" value={form.loanRules.maxBT} onChange={e => setForm((p: any) => ({ ...p, loanRules: { ...p.loanRules, maxBT: Number(e.target.value) } }))} /></div>
          </div>
          <div className="flex flex-wrap gap-5 mt-3">
            {[['btAllowed', 'BT Allowed'], ['topUpAllowed', 'Top Up Allowed'], ['odBT', 'OD BT'], ['nocRequired', 'NOC Required']].map(([key, label]) => (
              <label key={key} className="flex items-center gap-2 text-sm cursor-pointer">
                <input type="checkbox" className="rounded" checked={form.loanRules[key]} onChange={e => setForm((p: any) => ({ ...p, loanRules: { ...p.loanRules, [key]: e.target.checked } }))} />
                {label}
              </label>
            ))}
          </div>

          <SectionTitle>ROI</SectionTitle>
          <div className="grid grid-cols-4 gap-4">
            {[['categoryA', 'Category A'], ['categoryB', 'Category B'], ['categoryC', 'Category C'], ['categoryD', 'Category D']].map(([key, label]) => (
              <div key={key}><label className="label">{label}</label><input type="number" step="0.01" className="input" value={form.roi[key]} onChange={e => setForm((p: any) => ({ ...p, roi: { ...p.roi, [key]: Number(e.target.value) } }))} /></div>
            ))}
          </div>

          <div className="mt-4">
            <div className="flex items-center justify-between mb-2">
              <label className="label mb-0">Loan Amount Wise ROI</label>
              <button type="button" className="btn-secondary text-xs px-2 py-1" onClick={addRoiSlab}>+ Add Slab</button>
            </div>
            {(form.roi.loanAmountWiseROI || []).map((slab: any, i: number) => (
              <div key={i} className="grid grid-cols-4 gap-2 mb-2 items-center">
                <input type="number" className="input" placeholder="Min Amount" value={slab.minAmount} onChange={e => updateRoiSlab(i, 'minAmount', Number(e.target.value))} />
                <input type="number" className="input" placeholder="Max Amount" value={slab.maxAmount} onChange={e => updateRoiSlab(i, 'maxAmount', Number(e.target.value))} />
                <input type="number" step="0.01" className="input" placeholder="ROI %" value={slab.roi} onChange={e => updateRoiSlab(i, 'roi', Number(e.target.value))} />
                <button type="button" className="text-red-500 text-xs" onClick={() => removeRoiSlab(i)}>Remove</button>
              </div>
            ))}
          </div>

          <div className="mt-3">
            <label className="flex items-center gap-2 text-sm cursor-pointer">
              <input type="checkbox" className="rounded" checked={form.roi.openMarketDoable} onChange={e => setForm((p: any) => ({ ...p, roi: { ...p.roi, openMarketDoable: e.target.checked } }))} />
              Open Market: {form.roi.openMarketDoable ? 'Doable' : 'Not Doable'}
            </label>
          </div>

          <SectionTitle>Special Notes</SectionTitle>
          <textarea className="input" rows={3} value={form.specialNotes} onChange={e => setForm((p: any) => ({ ...p, specialNotes: e.target.value }))} />

          <SectionTitle>Additional Rules (Dynamic — no code changes needed)</SectionTitle>
          <p className="text-xs text-slate-500 mb-2">
            Add any extra eligibility rule. "Field" refers to a value on the application (e.g. <code>incomeDetails.totalExperience</code>). It will be compared against "Value" using the chosen operator.
          </p>
          {(form.customRules || []).map((rule: any, i: number) => (
            <div key={i} className="grid grid-cols-6 gap-2 mb-2 items-center bg-slate-50 p-2 rounded-lg">
              <input className="input col-span-2" placeholder="Rule name" value={rule.ruleName} onChange={e => updateCustomRule(i, 'ruleName', e.target.value)} />
              <input className="input" placeholder="Field path" value={rule.field} onChange={e => updateCustomRule(i, 'field', e.target.value)} />
              <select className="input" value={rule.operator} onChange={e => updateCustomRule(i, 'operator', e.target.value)}>
                {['>=', '<=', '>', '<', '==', '!=', 'in', 'notIn'].map(op => <option key={op} value={op}>{op}</option>)}
              </select>
              <input className="input" placeholder="Value" value={rule.value} onChange={e => updateCustomRule(i, 'value', e.target.value)} />
              <button type="button" className="text-red-500 text-xs" onClick={() => removeCustomRule(i)}>Remove</button>
            </div>
          ))}
          <button type="button" className="btn-secondary text-xs px-3 py-1.5 mt-1" onClick={addCustomRule}>+ Add More Rule</button>

          <div className="flex gap-3 justify-end mt-6 pt-4 border-t">
            <button className="btn-secondary" onClick={() => setShowModal(false)}>Cancel</button>
            <button className="btn-primary" onClick={handleSave} disabled={saving}>{saving ? 'Saving...' : 'Save Policy'}</button>
          </div>
        </div>
      </Modal>

      {/* ── View Modal ── */}
      <Modal open={!!viewing} onClose={() => setViewing(null)} title="Policy Details" size="max-w-2xl">
        {viewing && (
          <div className="space-y-3 text-sm max-h-[70vh] overflow-y-auto pr-1">
            <div className="grid grid-cols-2 gap-3">
              <div><span className="text-slate-500">Bank:</span> <span className="font-medium">{viewing.bankName || viewing.bankId?.bankName}</span> <span className="text-slate-400 text-xs">(...{(viewing.bankId?._id || viewing.bankId || '').toString().slice(-6)})</span></div>
              <div><span className="text-slate-500">Loan Type:</span> <span className="font-medium">{viewing.loanType}</span></div>
              <div><span className="text-slate-500">Version:</span> {viewing.policyVersion}</div>
              <div><span className="text-slate-500">Status:</span> <span className={viewing.status === 'active' ? 'badge-green' : 'badge-gray'}>{viewing.status}</span></div>
            </div>
            <SectionTitle>Eligibility</SectionTitle>
            <div className="grid grid-cols-3 gap-2 text-xs">
              <div>Age: {viewing.eligibility?.minAge}-{viewing.eligibility?.maxAge}</div>
              <div>Min Salary: ₹{(viewing.eligibility?.minSalary || 0).toLocaleString('en-IN')}</div>
              <div>Min CIBIL: {viewing.eligibility?.minCibil}</div>
              <div>Max FOIR: {viewing.eligibility?.maxFOIR}%</div>
              <div>Loan: ₹{(viewing.eligibility?.minLoanAmount || 0).toLocaleString('en-IN')} - ₹{(viewing.eligibility?.maxLoanAmount || 0).toLocaleString('en-IN')}</div>
              <div>Max Tenure: {viewing.eligibility?.maxTenure} mo</div>
            </div>
            <SectionTitle>Rules Summary</SectionTitle>
            <div className="grid grid-cols-2 gap-2 text-xs">
              <div>Max DPD: {viewing.dpdPolicy?.maxDPD} ({viewing.dpdPolicy?.allow90PlusDPD ? '90+ allowed' : '90+ not allowed'})</div>
              <div>Max Active Loans: {viewing.loanRules?.maxActiveLoans}</div>
              <div>Enquiries: ≤{viewing.enquiryPolicy?.maxEnquiries} in {viewing.enquiryPolicy?.windowDays} days</div>
              <div>Bounces: ≤{viewing.bouncePolicy?.maxBounces} in {viewing.bouncePolicy?.windowMonths} months</div>
            </div>
            {viewing.customRules?.length > 0 && (
              <>
                <SectionTitle>Custom Rules</SectionTitle>
                <ul className="list-disc list-inside text-xs space-y-1">
                  {viewing.customRules.map((r: any, i: number) => <li key={i}>{r.ruleName}: {r.field} {r.operator} {String(r.value)}</li>)}
                </ul>
              </>
            )}
            {viewing.specialNotes && (
              <>
                <SectionTitle>Special Notes</SectionTitle>
                <p className="text-xs text-slate-600">{viewing.specialNotes}</p>
              </>
            )}
          </div>
        )}
      </Modal>

      {/* ── Import from Excel Modal ── */}
      <Modal open={showImportModal} onClose={() => setShowImportModal(false)} title="Import Bank Policy from Excel" size="max-w-md">
        <div className="space-y-4">
          <p className="text-sm text-slate-600">
            Download the template, fill in your bank's criteria, then upload it here.
            Fields left blank keep their default values.
          </p>
          {!isBankUser && (
            <div>
              <label className="label">Bank *</label>
              <select className="input" value={importBankId} onChange={e => setImportBankId(e.target.value)}>
                <option value="">Select bank...</option>
                {banks.map(b => <option key={b._id} value={b._id}>{b.bankName} (...{b._id.slice(-6)})</option>)}
              </select>
            </div>
          )}
          {isBankUser && <div className="text-sm"><span className="text-slate-500">Bank:</span> <span className="font-medium">{banks[0]?.bankName}</span></div>}
          <div>
            <label className="label">Excel File (.xlsx / .xls) *</label>
            <input
              type="file"
              accept=".xlsx,.xls"
              className="input"
              onChange={e => setImportFile(e.target.files?.[0] || null)}
            />
          </div>
          <div className="flex justify-end gap-2 pt-2">
            <button className="btn-secondary" onClick={handleDownloadTemplate}><FiDownload className="inline mr-1" /> Download Template</button>
            <button className="btn-primary" onClick={handleImport} disabled={importing}>{importing ? 'Importing...' : 'Import'}</button>
          </div>
        </div>
      </Modal>

      <ConfirmModal
        open={!!toggleId}
        title="Change Policy Status"
        message="This will activate/deactivate the policy. Inactive policies are ignored during eligibility checks."
        onConfirm={handleToggle}
        onCancel={() => setToggleId(null)}
      />
    </div>
  );
}

export default AdminBankPolicy;
