import React, { useEffect, useState } from 'react';

import { adminAPI } from '../../services/api';
import { StatCard, LoadingSpinner, PageHeader, EmptyState, Modal, ConfirmModal } from '../../components/common';
import { FiGrid, FiUsers, FiFileText, FiBriefcase, FiTrendingUp, FiDollarSign, FiPlus, FiEdit, FiTrash2, FiDownload, FiUpload, FiEye, FiEyeOff, FiX } from 'react-icons/fi'; //FiEye } from 'react-icons/fi';//raksha
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, PieChart, Pie, Cell } from 'recharts';
import { toast } from 'react-toastify';
import { Link } from 'react-router-dom';
import { LOAN_TYPES } from '../../types';

const COLORS = ['#1B4FD8','#10B981','#F59E0B','#EF4444','#8B5CF6','#06B6D4','#F97316'];


//3-8
const isValidEmail = (email: string) => /^[^\s@]+@[^\s@]+\.[a-zA-Z]{2,}$/.test((email || '').trim());
const isValidMobile = (mobile: string) => /^[6-9]\d{9}$/.test((mobile || '').trim());


export function AdminDashboard() {
  const [stats, setStats] = useState<any>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    adminAPI.getDashboard().then(r => setStats(r.data)).catch(() => toast.error('Failed to load stats')).finally(() => setLoading(false));
  }, []);

  if (loading) return <LoadingSpinner fullPage />;
  if (!stats) return <EmptyState title="No data available" />;

  const monthlyData = (stats.monthlyStats || []).map((m: any) => ({
    name: `${m._id.month}/${m._id.year}`, count: m.count
  }));
  const pieData = (stats.loanTypeStats || []).map((l: any) => ({ name: l._id, value: l.count }));

  return (
    <div>
      <PageHeader title="Admin Dashboard" subtitle="Platform overview and analytics" breadcrumbs={['Admin', 'Dashboard']} />

      <div className="md:grid flex flex-col flex-wrap md:grid-cols-4 gap-3 mb-6">
        <StatCard title="Total Banks" value={stats.totalBanks || 0} icon={<FiGrid />} color="text-blue-600 bg-blue-50" />
        <StatCard title="DSA Companies" value={stats.totalCompanies || 0} icon={<FiBriefcase />} color="text-violet-600 bg-violet-50" />
        <StatCard title="Connectors" value={stats.totalConnectors || 0} icon={<FiUsers />} color="text-emerald-600 bg-emerald-50" />
        <StatCard title="Total Applications" value={stats.totalApplications || 0} icon={<FiFileText />} color="text-amber-600 bg-amber-50" />
      </div>

      <div className="md:grid flex flex-col flex-wrap md:grid-cols-4 gap-3 mb-6">
        <StatCard title="Today's Applications" value={stats.todayApplications || 0} icon={<FiTrendingUp />} color="text-primary bg-primary-50" />
        <StatCard title="Month Applications" value={stats.monthApplications || 0} icon={<FiFileText />} color="text-teal-600 bg-teal-50" />
        <StatCard title="Total Disbursed" value={`₹${((stats.totalDisbursed || 0)/100000).toFixed(1)}L`} icon={<FiDollarSign />} color="text-emerald-600 bg-emerald-50" />
        <StatCard title="Loan Types Active" value={pieData.length} icon={<FiBriefcase />} color="text-orange-600 bg-orange-50" />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 mb-6">
        <div className="card">
          <h3 className="font-semibold text-slate-800 mb-4">Monthly Applications</h3>
          <ResponsiveContainer width="100%" height={220}>
            <BarChart data={monthlyData}>
              <CartesianGrid strokeDasharray="3 3" stroke="#f1f5f9" />
              <XAxis dataKey="name" tick={{ fontSize: 11 }} />
              <YAxis tick={{ fontSize: 11 }} />
              <Tooltip />
              <Bar dataKey="count" fill="#1B4FD8" radius={[4, 4, 0, 0]} />
            </BarChart>
          </ResponsiveContainer>
        </div>
        <div className="card">
          <h3 className="font-semibold text-slate-800 mb-4">Loan Type Distribution</h3>
          {pieData.length > 0 ? (
            <ResponsiveContainer width="100%" height={220}>
              <PieChart>
                <Pie data={pieData} cx="50%" cy="50%" innerRadius={50} outerRadius={90} dataKey="value" label={({ name, percent }: any) => `${name?.split(' ')[0]} ${((percent || 0) * 100).toFixed(0)}%`} labelLine={false} fontSize={10}>
                  {pieData.map((_: any, i: number) => <Cell key={i} fill={COLORS[i % COLORS.length]} />)}
                </Pie>
                <Tooltip />
              </PieChart>
            </ResponsiveContainer>
          ) : <EmptyState title="No applications yet" />}
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="card">
          <div className="flex items-center justify-between mb-4">
            <h3 className="font-semibold text-slate-800">Quick Actions</h3>
          </div>
          <div className="grid grid-cols-2 gap-3">
            {[
              { label: 'Add Bank', href: '/admin/banks', icon: <FiGrid /> },
              { label: 'Add Company', href: '/admin/companies', icon: <FiBriefcase /> },
              { label: 'Add Connector', href: '/admin/connectors', icon: <FiUsers /> },
              { label: 'View Applications', href: '/admin/applications', icon: <FiFileText /> },
              { label: 'Reports', href: '/admin/reports', icon: <FiTrendingUp /> },
              { label: 'Audit Logs', href: '/admin/audit-logs', icon: <FiEye /> },
            ].map((a, i) => (
              <Link key={i} to={a.href} className="flex items-center gap-2 p-3 border border-slate-200 rounded-lg hover:border-primary hover:bg-primary-50 text-slate-700 hover:text-primary transition-all text-sm font-medium">
                {a.icon} {a.label}
              </Link>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

