 //raksha
 const handleDocUpload = async (files: FileList) => {
  const allowedTypes = ['application/pdf', 'image/jpeg', 'image/jpg', 'image/png'];
  const remainingSlots = 10 - (form.documents || []).length;

  if (remainingSlots <= 0) {
    toast.error('Maximum 10 documents allowed');
    return;
  }

  const allFiles = Array.from(files);
  const validFiles = allFiles.filter(f => allowedTypes.includes(f.type));
  const fileArr = validFiles.slice(0, remainingSlots);

  if (fileArr.length === 0) {
    toast.error('Only PDF, JPG, PNG files are allowed');
    return;
  }
  if (validFiles.length < allFiles.length) {
    toast.error('Some files were skipped — only PDF, JPG, PNG are allowed');
  }
  if (validFiles.length > remainingSlots) {
    toast.error(`Only ${remainingSlots} more file(s) can be added (max 10 total)`);
  }

  setUploadingDocs(true);
  try {
    const uploaded: any[] = [];
    for (const file of fileArr) {
      const fd = new FormData();
      fd.append('file', file);
      const res = await fetch(`/api/v1/documents/upload?folder=others`, {
        method: 'POST',
        headers: { Authorization: `Bearer ${localStorage.getItem('token')}` },
        body: fd
      });
      const data = await res.json();
      uploaded.push({ name: file.name, url: data.url });
    }
    setForm((p: any) => ({ ...p, documents: [...(p.documents || []), ...uploaded] }));
    toast.success(`${uploaded.length} document(s) uploaded`);
  } catch { toast.error('Document upload failed'); }
  finally { setUploadingDocs(false); }
};

