export interface BankAssignment {
  _id: string; bankId: string; bankName: string; smId?: string; smName?: string;
  status: string; unmaskRequested: boolean; unmaskApproved: boolean;
  sanctionAmount?: number; sanctionDate?: string; sanctionLetterUrl?: string;
  disbursementAmount?: number; disbursementDate?: string;
  rejectionReason?: string; tatBreached?: boolean;
  statusHistory: Array<{ status: string; changedByName: string; changedAt: string; notes?: string }>;
  queries: Array<{ _id: string; raisedByName: string; question: string; answer?: string; status: string; raisedAt: string }>;
}

export interface LoanApplication {
  _id: string; applicationId: string; loanType: string; loanAmount: number; loanPurpose?: string;
  connectorId: any; companyId: any; overallStatus: string;
  applicantDetails: { name: string; mobileRaw?: string; mobileMasked?: string; email?: string; emailMasked?: string; dob?: string; dobMasked?: string; aadhaarMasked?: string; panMasked?: string; presentAddress?: string; maritalStatus?: string; qualification?: string; motherName?: string; fatherName?: string; };
  incomeDetails: { employmentType?: string; companyName?: string; netSalary?: number; designation?: string; totalExperience?: number; };
  // cibilScore?: number; bankAssignments: BankAssignment[];
  documents: any; createdAt: string; updatedAt: string;
}

export interface Company { _id: string; companyName: string; city?: string; email?: string; mobile?: string; status: string; connectorRelations?: any[]; bankingRelations?: any[]; }
export interface Bank { _id: string; bankName: string; dsaCode?: string; supportedLoanTypes?: string[]; city?: string; status: string; }
export interface Connector { _id: string; name: string; email?: string; mobile?: string; totalLeads?: number; status: string; companyRelations?: any[]; }

// ── Bank Policy module (new, separate) ──────────────────────────────────────
export interface BankPolicyEligibility {
  minAge: number; maxAge: number; minSalary: number; minCibil: number;
  maxFOIR: number; maxMultiplier: number; maxLoanAmount: number;
  minLoanAmount: number; maxTenure: number;
}

export interface BankPolicyCustomRule {
  _id?: string; ruleName: string; field: string;
  operator: '>=' | '<=' | '>' | '<' | '==' | '!=' | 'in' | 'notIn';
  value: any; failMessage?: string;
}

export interface BankPolicy {
  _id: string;
  bankId: string | { _id: string; bankName: string };
  bankName: string;
  loanType: string;
  policyVersion: string;
  effectiveDate: string;
  status: 'active' | 'inactive';
  eligibility: BankPolicyEligibility;
  enquiryPolicy: { windowDays: 30 | 60 | 90; maxEnquiries: number };
  bouncePolicy: { windowMonths: 3 | 6 | 12; maxBounces: number };
  employmentPolicy: {
    allowedProfiles: string[]; restrictedProfiles: string[];
    allowedCompanies: string[]; restrictedCompanies: string[];
  };
  dpdPolicy: { maxDPD: number; allow90PlusDPD: boolean };
  loanRules: {
    maxActiveLoans: number; maxSTPL: number; btAllowed: boolean;
    topUpAllowed: boolean; maxBT: number; odBT: boolean; nocRequired: boolean;
  };
  roi: {
    categoryA: number; categoryB: number; categoryC: number; categoryD: number;
    loanAmountWiseROI: { minAmount: number; maxAmount: number; roi: number }[];
    openMarketDoable: boolean;
  };
  specialNotes?: string;
  customRules: BankPolicyCustomRule[];
  createdAt?: string; updatedAt?: string;
}

export interface EligibilityCheck { label: string; passed: boolean; message: string; }
export interface EligibilityResult {
  eligible: boolean;
  checks: EligibilityCheck[];
  policyId?: string;
  policyVersion?: string;
  evaluatedAt?: string;
}
