function BankIllustration() {
  const chips = [
    { icon: <FiShield />, pos: "top-2 left-6" },
    { icon: <FiBarChart2 />, pos: "top-16 -left-2" },
    { icon: <FiFileText />, pos: "top-4 right-2" },
    { icon: <FiTrendingUp />, pos: "bottom-10 left-2" },
  ];
  return (
    <div className="relative w-64 h-64 mx-auto">
      {/* glow ring */}
      <div className="absolute inset-0 rounded-full border border-white/10" />
      <div className="absolute inset-6 rounded-full border border-white/10" />

      {chips.map((c, i) => (
        <motion.div
          key={i}
          animate={{ y: [0, -8, 0] }}
          transition={{
            repeat: Infinity,
            duration: 3 + i * 0.4,
            ease: "easeInOut",
            delay: i * 0.3,
          }}
          className={`absolute ${c.pos} w-10 h-10 rounded-xl bg-primary-500/40 border border-white/20 backdrop-blur flex items-center justify-center text-white text-base shadow-lg`}
        >
          {c.icon}
        </motion.div>
      ))}

      {/* bank building */}
      <motion.svg
        animate={{ y: [0, -6, 0] }}
        transition={{ repeat: Infinity, duration: 4, ease: "easeInOut" }}
        viewBox="0 0 200 180"
        className="absolute inset-0 w-full h-full drop-shadow-2xl"
      >
        <defs>
          <linearGradient id="bankGrad" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor="#EFF4FF" />
            <stop offset="100%" stopColor="#93b4ff" />
          </linearGradient>
        </defs>
        <ellipse
          cx="100"
          cy="158"
          rx="55"
          ry="8"
          fill="#0b1f6b"
          opacity="0.5"
        />
        <polygon points="100,40 150,72 50,72" fill="url(#bankGrad)" />
        <rect x="55" y="76" width="10" height="56" fill="url(#bankGrad)" />
        <rect x="75" y="76" width="10" height="56" fill="url(#bankGrad)" />
        <rect x="95" y="76" width="10" height="56" fill="url(#bankGrad)" />
        <rect x="115" y="76" width="10" height="56" fill="url(#bankGrad)" />
        <rect x="135" y="76" width="10" height="56" fill="url(#bankGrad)" />
        <rect x="46" y="134" width="108" height="10" fill="url(#bankGrad)" />
      </motion.svg>
    </div>
  );
}

