const SIDEBAR_STORAGE_KEY = "bz_sidebar_collapsed";

/*  Sidebar                                                                   */
/* -------------------------------------------------------------------------- */

const Sidebar: React.FC<{ collapsed: boolean; onToggle: () => void }> = ({
  collapsed,
  onToggle,
}) => {
  const { user } = useAuth();
  const role = user?.role || "connector";
  const links = NAV_LINKS[role] || [];
  const roleLabel =
    role === "sm"
      ? "Sales Manager"
      : role.charAt(0).toUpperCase() + role.slice(1);

  return (
    <aside
      className={`flex flex-col transition-all duration-300 ${collapsed ? "w-16" : "w-60"} h-screen fixed left-0 top-0 z-30 overflow-hidden`}
      style={{
        background:
          "linear-gradient(180deg, #0c1445 0%, #0a1030 55%, #080b24 100%)",
      }}
    >
      {/* header / brand */}
      <div className="relative flex items-center h-16 px-4 border-b border-white/10 shrink-0">
        {!collapsed ? (
          <div className="flex items-center gap-2.5">
            <div className="w-9 h-9 rounded-xl flex items-center justify-center bg-gradient-to-br from-primary-500 to-primary-700 shadow-lg shadow-primary/30 shrink-0">
              <FiShield className="text-white text-base" />
            </div>
            <div className="leading-tight">
              <p className="font-extrabold text-white text-[15px] tracking-wide">
                BANK ZONE
              </p>
              <p className="text-[10px] text-slate-400">Smart Loan Platform</p>
            </div>
          </div>
        ) : (
          <div className="w-9 h-9 rounded-xl flex items-center justify-center bg-gradient-to-br from-primary-500 to-primary-700 shadow-lg shadow-primary/30 mx-auto">
            <FiShield className="text-white text-base" />
          </div>
        )}
        <button
          onClick={onToggle}
          className={`text-slate-400 hover:text-white transition-colors ${collapsed ? "hidden" : "ml-auto"}`}
        >
          <FiX />
        </button>
      </div>
      {collapsed && (
        <button
          onClick={onToggle}
          className="mx-auto mt-2 text-slate-400 hover:text-white transition-colors"
        >
          <FiMenu />
        </button>
      )}

      {/* nav links */}
      <nav className="relative flex-1 px-3 py-4 space-y-1 overflow-y-auto min-h-0">
        {links.map((link) => (
          <NavLink
            key={link.href}
            to={link.href}
            className={({ isActive }) =>
              `flex items-center gap-3 rounded-xl px-3 py-2.5 text-sm font-medium transition-colors ${
                collapsed ? "justify-center px-2" : ""
              } ${
                isActive
                  ? "bg-primary text-white shadow-lg shadow-primary/30"
                  : "text-slate-400 hover:bg-white/5 hover:text-white"
              }`
            }
          >
            <span className="text-lg shrink-0">{link.icon}</span>
            {!collapsed && <span className="truncate">{link.label}</span>}
          </NavLink>
        ))}
      </nav>

      {/* decorative wave, purely visual */}
      <svg
        className="w-full h-12 opacity-40 pointer-events-none shrink-0"
        viewBox="0 0 240 48"
        preserveAspectRatio="none"
      >
        <path
          d="M0,32 C40,8 80,44 120,24 C160,6 200,36 240,16"
          fill="none"
          stroke="url(#sidebarWave)"
          strokeWidth="1.5"
        />
        <defs>
          <linearGradient id="sidebarWave" x1="0" y1="0" x2="1" y2="0">
            <stop offset="0%" stopColor="#1B4FD8" stopOpacity="0" />
            <stop offset="50%" stopColor="#5B8CFF" stopOpacity="0.9" />
            <stop offset="100%" stopColor="#1B4FD8" stopOpacity="0" />
          </linearGradient>
        </defs>
      </svg>

      {/* profile footer */}
      {user && (
        <div className="border-t border-white/10 p-3 shrink-0">
          {!collapsed ? (
            <button className="w-full flex items-center gap-2.5 rounded-xl p-1.5 hover:bg-white/5 transition-colors">
              <div className="w-9 h-9 rounded-full bg-gradient-to-br from-primary-500 to-primary-700 flex items-center justify-center text-white font-bold text-sm shrink-0">
                {user.name?.charAt(0).toUpperCase()}
              </div>
              <div className="min-w-0 text-left">
                <p className="text-sm font-semibold text-white truncate">
                  {user.name}
                </p>
                <p className="text-[11px] text-slate-400 truncate">
                  {roleLabel}
                </p>
              </div>
            </button>
          ) : (
            <div className="w-9 h-9 mx-auto rounded-full bg-gradient-to-br from-primary-500 to-primary-700 flex items-center justify-center text-white font-bold text-sm">
              {user.name?.charAt(0).toUpperCase()}
            </div>
          )}
        </div>
      )}
    </aside>
  );
};

