const Topbar: React.FC<{ sidebarCollapsed: boolean }> = ({
  sidebarCollapsed,
}) => {
  const { user, logout, unreadCount, setUnreadCount } = useAuth();
  const navigate = useNavigate();
  const [showNotifs, setShowNotifs] = useState(false);
  const [notifs, setNotifs] = useState<any[]>([]);
  const [showProfile, setShowProfile] = useState(false);

  const loadNotifs = async () => {
    try {
      const res = await notifAPI.getAll({ limit: 10 });
      setNotifs(res.data.notifications);
      setUnreadCount(res.data.unreadCount);
    } catch {}
  };

  const handleNotifToggle = () => {
    setShowNotifs((v) => !v);
    if (!showNotifs) loadNotifs();
  };

  const markAllRead = async () => {
    await notifAPI.markAllRead();
    setUnreadCount(0);
    setNotifs((prev) => prev.map((n) => ({ ...n, isRead: true })));
  };

  const handleLogout = async () => {
    await logout();
    navigate("/login");
  };

  const marginLeft = sidebarCollapsed ? "ml-16" : "ml-60";

  return (
    <header
      className={`fixed top-0 right-0 h-16 bg-white border-b border-slate-200 flex items-center justify-between px-6 z-20 transition-all duration-300 left-0 ${marginLeft}`}
    >
      <div className="text-sm text-slate-400 hidden sm:block">
        Welcome back,{" "}
        <span className="font-semibold text-slate-700">{user?.name}</span>
      </div>
      <div className="flex items-center gap-3 ml-auto">
        <div className="relative">
          {/* <button
            onClick={handleNotifToggle}
            className="relative p-2 text-slate-500 hover:text-primary hover:bg-primary-50 rounded-lg transition-colors"
          >
            <FiBell className="text-lg" />
            {unreadCount > 0 && (
              <span className="absolute -top-0.5 -right-0.5 w-4 h-4 bg-red-500 text-white text-xs rounded-full flex items-center justify-center font-bold">
                {unreadCount > 9 ? "9+" : unreadCount}
              </span>
            )}
          </button> */}
          {showNotifs && (
            <>
              {/* Backdrop - dims page behind so dropdown doesn't visually blend/overlap */}
              <div
                className="fixed inset-0 bg-black/40 sm:bg-transparent z-40"
                onClick={() => setShowNotifs(false)}
              />

              <div className="fixed sm:absolute left-2 right-2 sm:left-auto sm:right-0 bottom-2 sm:bottom-auto top-auto sm:top-full mt-0 sm:mt-1 w-auto sm:w-80 max-w-full bg-white rounded-xl shadow-xl border border-slate-200 z-50 max-h-[70vh] sm:max-h-none flex flex-col">
                <div className="flex items-center justify-between p-2.5 border-b shrink-0">
                  <h3 className="font-semibold text-slate-800 text-sm">
                    Notifications
                  </h3>
                  <button
                    onClick={markAllRead}
                    className="text-xs text-primary hover:underline"
                  >
                    Mark all read
                  </button>
                </div>
                <div className="overflow-y-auto  flex-1 sm:max-h-80 sm:flex-none">
                  {notifs.length === 0 ? (
                    <p className="text-center text-slate-400 text-sm py-6">
                      No notifications
                    </p>
                  ) : (
                    notifs.map((n) => (
                      <div
                        key={n._id}
                        className={`p-2.5 border-b hover:bg-slate-50 cursor-pointer ${!n.isRead ? "bg-blue-50" : ""}`}
                      >
                        <p className="text-sm font-medium text-slate-800 break-words">
                          {n.title}
                        </p>
                        <p className="text-xs text-slate-500 mt-0.5 break-words">
                          {n.message}
                        </p>
                        <p className="text-xs text-slate-400 mt-1">
                          {new Date(n.createdAt).toLocaleString("en-IN")}
                        </p>
                      </div>
                    ))
                  )}
                </div>
                <div className="p-2 border-t shrink-0">
                  <button
                    onClick={() => {
                      navigate(`/${user?.role}/notifications`);
                      setShowNotifs(false);
                    }}
                    className="text-xs text-primary hover:underline w-full text-center"
                  >
                    View all notifications
                  </button>
                </div>
              </div>
            </>
          )}
        </div>

        {/* Profile */}
        <div className="relative">
          <button
            onClick={() => setShowProfile((v) => !v)}
            className="flex items-center gap-2 p-1.5 rounded-lg hover:bg-slate-100 transition-colors"
          >
            <div className="w-8 h-8 rounded-full bg-primary text-white flex items-center justify-center font-bold text-sm">
              {user?.name?.charAt(0).toUpperCase()}
            </div>
          </button>
          {showProfile && (
            <div className="absolute right-0 top-full mt-1 w-48 bg-white rounded-xl shadow-xl border border-slate-200 z-50">
              <div className="p-3 border-b">
                <p className="font-semibold text-sm text-slate-800">
                  {user?.name}
                </p>
                <p className="text-xs text-slate-400">{user?.email}</p>
              </div>
              <button
                onClick={handleLogout}
                className="w-full flex items-center gap-2 px-4 py-2.5 text-sm text-red-600 hover:bg-red-50 transition-colors"
              >
                <FiLogOut /> Logout
              </button>
            </div>
          )}
        </div>
      </div>
    </header>
  );
};

export const DashboardLayout: React.FC<{ children?: React.ReactNode }> = ({
  children,
}) => {
  const [collapsed, setCollapsed] = useState<boolean>(() => {
    // Check if it's a small device (mobile)
    const isSmallDevice = window.innerWidth < 768;

    // If small device, start collapsed
    if (isSmallDevice) {
      return true;
    }

    // Otherwise check session storage
    try {
      return sessionStorage.getItem(SIDEBAR_STORAGE_KEY) === "1";
    } catch {
      return false;
    }
  });

  // Listen for window resize to handle device changes
  useEffect(() => {
    const handleResize = () => {
      const isSmallDevice = window.innerWidth < 768;
      // Only auto-collapse on small devices if not manually toggled
      if (isSmallDevice) {
        setCollapsed(true);
      }
    };

    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, []);

  useEffect(() => {
    try {
      sessionStorage.setItem(SIDEBAR_STORAGE_KEY, collapsed ? "1" : "0");
    } catch {}
  }, [collapsed]);

  const marginLeft = collapsed ? "ml-16" : "ml-60";

  return (
    <div className="min-h-screen bg-background">
      <Sidebar collapsed={collapsed} onToggle={() => setCollapsed((v) => !v)} />
      <Topbar sidebarCollapsed={collapsed} />
      <main className={`transition-all duration-300 ${marginLeft} pt-16`}>
        <div className="p-6 max-w-7xl mx-auto">{children ?? <Outlet />}</div>
      </main>
    </div>
  );
};

export default DashboardLayout;
