import React, { useEffect, useState } from 'react';
import { companyCategoryAPI, adminAPI, bankPolicyAPI } from '../../services/api';
import { PageHeader, LoadingSpinner, EmptyState, Modal, ConfirmModal } from '../../components/common';
import { FiDownload, FiUpload, FiTrash2 } from 'react-icons/fi';
import { toast } from 'react-toastify';
import { useAuth } from '../../context/AuthContext';

export function CompanyCategoryPage() {
  const { user } = useAuth();
  const isBankUser = user?.role === 'bank';

  const [banks, setBanks] = useState<any[]>([]);
  const [rows, setRows] = useState<any[]>([]);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');

  const [showImportModal, setShowImportModal] = useState(false);
  const [importBankId, setImportBankId] = useState('');
  const [importFile, setImportFile] = useState<File | null>(null);
  const [importMode, setImportMode] = useState<'merge' | 'replace'>('merge');
  const [importing, setImporting] = useState(false);
  const [deleteId, setDeleteId] = useState<string | null>(null);

  // Which bank's list is currently being viewed (admin can switch; bank user is locked to their own)
  const [viewBankId, setViewBankId] = useState('');

  useEffect(() => {
    if (isBankUser) {
      bankPolicyAPI.getMyBank().then(r => {
        setBanks([r.data]);
        setViewBankId(r.data._id);
        setImportBankId(r.data._id);
      }).catch(() => toast.error('No bank profile linked to this account — contact Admin'));
    } else {
      adminAPI.getBanks({ limit: 200 }).then(r => setBanks(r.data.banks || []));
    }
  }, [isBankUser]);

  const load = () => {
    if (!viewBankId) return;
    setLoading(true);
    companyCategoryAPI.getAll({ bankId: viewBankId, search, limit: 100 })
      .then(r => { setRows(r.data.rows); setTotal(r.data.total); })
      .finally(() => setLoading(false));
  };

  useEffect(() => { load(); }, [viewBankId, search]);

  const handleDownloadTemplate = async () => {
    try {
      const res = await companyCategoryAPI.downloadTemplate();
      const url = window.URL.createObjectURL(new Blob([res.data]));
      const a = document.createElement('a');
      a.href = url; a.download = 'company-category-template.xlsx';
      document.body.appendChild(a); a.click(); a.remove();
      window.URL.revokeObjectURL(url);
    } catch { toast.error('Failed to download template'); }
  };

  const openImport = () => {
    setImportFile(null);
    setImportMode('merge');
    setImportBankId(isBankUser && banks[0] ? banks[0]._id : viewBankId || '');
    setShowImportModal(true);
  };

  const handleImport = async () => {
    if (!importFile) { toast.error('Please choose an Excel file'); return; }
    if (!isBankUser && !importBankId) { toast.error('Please select a bank'); return; }
    setImporting(true);
    try {
      const res = await companyCategoryAPI.importExcel(importFile, importBankId, importMode === 'replace' ? 'replace' : undefined);
      toast.success(res.data?.message || 'Imported successfully');
      setShowImportModal(false);
      setViewBankId(importBankId);
      load();
    } catch (err: any) { toast.error(err?.response?.data?.message || 'Import failed'); }
    finally { setImporting(false); }
  };

  const handleDelete = async () => {
    if (!deleteId) return;
    try { await companyCategoryAPI.deleteOne(deleteId); toast.success('Removed'); setDeleteId(null); load(); }
    catch { toast.error('Failed to remove'); }
  };

  return (
    <div>
      <PageHeader
        title="Company Category"
        subtitle={`${total} companies mapped${!isBankUser && viewBankId ? '' : ''}`}
        breadcrumbs={[isBankUser ? 'Bank' : 'Admin', 'Company Category']}
        actions={
          <div className="flex items-center gap-2">
            <button className="btn-secondary flex items-center gap-2 text-sm" onClick={handleDownloadTemplate}><FiDownload /> Template</button>
            <button className="btn-primary flex items-center gap-2 text-sm" onClick={openImport}><FiUpload /> Import Excel</button>
          </div>
        }
      />

      <div className="card">
        <div className="flex items-center justify-between gap-3 mb-4 flex-wrap">
          {!isBankUser && (
            <select className="input max-w-xs" value={viewBankId} onChange={e => setViewBankId(e.target.value)}>
              <option value="">Select bank to view...</option>
              {banks.map(b => <option key={b._id} value={b._id}>{b.bankName} (...{b._id.slice(-6)})</option>)}
            </select>
          )}
          <input className="input max-w-xs" placeholder="Search company..." value={search} onChange={e => setSearch(e.target.value)} />
        </div>

        {!viewBankId ? (
          <EmptyState title="Select a bank" description="Choose a bank above to view its Company → Category list." />
        ) : loading ? <LoadingSpinner /> : rows.length === 0 ? (
          <EmptyState title="No companies mapped yet" description="Download the template, fill Company Name + Category, and import it." action={<button className="btn-primary" onClick={openImport}>Import Excel</button>} />
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full">
              <thead className="bg-slate-50">
                <tr>
                  <th className="table-th">Company Name</th>
                  <th className="table-th">Category</th>
                  <th className="table-th">Actions</th>
                </tr>
              </thead>
              <tbody>
                {rows.map((r: any) => (
                  <tr key={r._id} className="table-row">
                    <td className="table-td font-medium">{r.companyName}</td>
                    <td className="table-td"><span className="badge-blue">{r.category}</span></td>
                    <td className="table-td">
                      <button onClick={() => setDeleteId(r._id)} className="text-red-500 hover:text-red-700 p-1" title="Remove"><FiTrash2 /></button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* ── Import Modal ── */}
      <Modal open={showImportModal} onClose={() => setShowImportModal(false)} title="Import Company → Category" size="max-w-md">
        <div className="space-y-4">
          <p className="text-sm text-slate-600">
            Sheet must have 2 columns: <strong>Company Name</strong> and <strong>Category</strong> (e.g. A/B/C/D).
            Re-importing updates the category for companies already in the list and adds any new ones.
          </p>
          {!isBankUser && (
            <div>
              <label className="label">Bank *</label>
              <select className="input" value={importBankId} onChange={e => setImportBankId(e.target.value)}>
                <option value="">Select bank...</option>
                {banks.map(b => <option key={b._id} value={b._id}>{b.bankName} (...{b._id.slice(-6)})</option>)}
              </select>
            </div>
          )}
          {isBankUser && <div className="text-sm"><span className="text-slate-500">Bank:</span> <span className="font-medium">{banks[0]?.bankName}</span></div>}
          <div>
            <label className="label">Excel File (.xlsx / .xls) *</label>
            <input type="file" accept=".xlsx,.xls" className="input" onChange={e => setImportFile(e.target.files?.[0] || null)} />
          </div>
          <div>
            <label className="flex items-center gap-2 text-sm cursor-pointer">
              <input type="checkbox" className="rounded" checked={importMode === 'replace'} onChange={e => setImportMode(e.target.checked ? 'replace' : 'merge')} />
              Replace this bank's entire list instead of merging
            </label>
          </div>
          <div className="flex justify-end gap-2 pt-2">
            <button className="btn-secondary" onClick={handleDownloadTemplate}><FiDownload className="inline mr-1" /> Download Template</button>
            <button className="btn-primary" onClick={handleImport} disabled={importing}>{importing ? 'Importing...' : 'Import'}</button>
          </div>
        </div>
      </Modal>

      <ConfirmModal
        open={!!deleteId}
        title="Remove Company Mapping"
        message="This company will no longer have a category for this bank."
        onConfirm={handleDelete}
        onCancel={() => setDeleteId(null)}
      />
    </div>
  );
}

export default CompanyCategoryPage;
